import numpy as np

def engine(grid, action, data):
    if action == 4:
        h, w = grid.shape
        new_grid = grid.copy()
        if data is None:
            return new_grid
        px, py = data['x'], data['y']
        logical_px, logical_py = px // 1, py // 1
        if logical_px < 0 or logical_px >= w or logical_py < 0 or logical_py >= h:
            return new_grid
        # Determine which object is clicked
        clicked_obj = None
        for r in range(h):
            for c in range(w):
                if grid[r, c] == 1:
                    if c == logical_px and r == logical_py:
                        clicked_obj = (r, c)
                        break
            if clicked_obj:
                break
        
        if clicked_obj:
            r_click, c_click = clicked_obj
            # Clear the clicked cell
            new_grid[r_click, c_click] = 0
            # Find the object connected to this cell
            # BFS to find the object
            visited = np.zeros_like(grid, dtype=bool)
            queue = [(r_click, c_click)]
            visited[r_click, c_click] = True
            obj_cells = []
            while queue:
                curr_r, curr_c = queue.pop(0)
                obj_cells.append((curr_r, curr_c))
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = curr_r + dr, curr_c + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr, nc] == 1 and not visited[nr, nc]:
                        visited[nr, nc] = True
                        queue.append((nr, nc))
            
            # Move the object down
            for r, c in obj_cells:
                new_grid[r, c] = 0
                new_grid[r + 1, c] = 1
            return new_grid
        else:
            return new_grid
    elif action == 5:
        h, w = grid.shape
        new_grid = grid.copy()
        # Fill the entire grid with color 1
        new_grid[:] = 1
        # Clear the top row
        new_grid[0, :] = 0
        return new_grid
    else:
        return grid

